# filename: parse_houses.py

def parse_layout(file_path):
    with open(file_path, 'r') as f:
        lines = [line.rstrip('\n') for line in f]
    # Identify the road line by the maximum count of '-'
    road_idx = max(range(len(lines)), key=lambda i: lines[i].count('-'))
    house_positions = []
    for idx in (road_idx - 1, road_idx + 1):
        if 0 <= idx < len(lines):
            for pos, ch in enumerate(lines[idx]):
                if ch == 'H':
                    house_positions.append(pos)
    return sorted(set(house_positions))

